import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long currentMin = 1L << 32;
        long bestNumerator = 1L << 32;
        long bestDenominator = 1L << 32;

        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        for (long denom = 1; denom <= n; ++denom) {
            long num = Math.max(x * denom / y - 10, 0);
            for (int offset = 0; offset < 20; ++offset) {
                long diff = Math.abs(x * denom - (num + offset) * y);
                if (currentMin * denom > diff * bestDenominator) {
                    currentMin = diff;
                    bestNumerator = num + offset;
                    bestDenominator = denom;
                } else if (currentMin * denom == diff * bestDenominator) {
                    if (bestDenominator > denom || (bestDenominator == denom && bestNumerator > num + offset)) {
                        currentMin = diff;
                        bestNumerator = num + offset;
                        bestDenominator = denom;
                    }
                }
            }
        }
        System.out.println(bestNumerator + "/" + bestDenominator);
        scanner.close();
    }
}
